Night.views = (()=>{
 const esc=Night.escape;
 function heading(code,title,description){return `<div class="page-heading"><p class="eyebrow">${code}</p><h1 tabindex="-1">${title}</h1><p>${description}</p><span class="page-corner" aria-hidden="true">↗</span></div>`;}
 function card(post,index){return `<article class="journal-card"><a class="post" href="#/post/${post.id}"><div class="post-art art-${index}" aria-hidden="true">${esc(post.symbol)}</div><div><div class="post-meta"><span>${post.category} / LOG</span>${post.date}</div><h2>${post.title}</h2><p>${post.summary}</p></div><span class="post-arrow" aria-hidden="true">↗</span></a><button class="save-post" data-save="${post.id}" aria-pressed="${Night.favoriteIds().includes(post.id)}" aria-label="收藏：${post.title}">${Night.favoriteIds().includes(post.id)?'★ 已收藏':'☆ 收藏'}</button></article>`;}
 function home(){return document.querySelector('#home-template').innerHTML+`<div class="ticker" aria-hidden="true"><div>NEON / 零界 <span>✳</span> CODE THE UNKNOWN. <span>✳</span> STAY CURIOUS. <span>✳</span> BUILD SOMETHING COOL. <span>✳</span> NEON / 零界 <span>✳</span></div></div><section class="section home-signal"><div class="section-heading"><div><p class="eyebrow">LATEST TRANSMISSIONS</p><h2>构建中的<span>思维信号</span></h2></div><a class="text-link" href="#/journal">查看全部日志 ↗</a></div><div class="posts">${Night.posts.slice(0,2).map(card).join('')}</div></section>${Night.gallery.preview()}<section class="home-access"><div><p class="eyebrow">PERSONAL ID / N—0001</p><h2>我是 <span class="neon-name">NΞON<span>// 零界</span></span></h2><p>把赛博朋克视觉、网页交互和个人表达，写进同一个数字空间。</p></div><a href="#/about" class="button primary">读取个人档案 ↗</a></section>`;}
 function journal(){return `<section class="section route-section">${heading('01 / TRANSMISSION ARCHIVE','我的<span>构建日志</span>','这里记录 NIGHT.LOG 的设计取舍、代码实现和迭代过程。')}<div class="journal-tools"><div class="filters" role="group" aria-label="文章分类">${['全部','技术','设计','收藏'].map((v,i)=>`<button data-filter="${v}" aria-pressed="${i===0}" class="${i===0?'selected':''}">${v==='全部'?'全部信号':v==='收藏'?'★ 我的收藏':v}</button>`).join('')}</div><label class="search"><span aria-hidden="true">⌕</span><input type="search" id="search" placeholder="搜索标题或内容…" aria-label="搜索日志"></label></div><div class="result-line"><p id="result-count" role="status"></p><button class="small-button" id="reset-search">重置筛选 ↺</button></div><div class="posts" id="posts">${Night.posts.map(card).join('')}</div><div id="empty" class="empty-state" hidden><span aria-hidden="true">∅</span><h2>未检索到信号</h2><p>换一个关键词，或重置筛选后继续浏览。</p><button class="button primary" id="empty-reset">显示全部日志 ↗</button></div><p class="subtle archive-note">收藏仅保存在当前浏览器，不需要登录。</p></section>`;}
 function article(id){const post=Night.posts.find(p=>p.id===id);if(!post)return missing();return `<article class="section article-view"><div class="article-top"><a class="text-link" href="#/journal">← 返回全部日志</a><button class="small-button" data-save="${id}" aria-pressed="${Night.favoriteIds().includes(id)}">${Night.favoriteIds().includes(id)?'★ 已收藏':'☆ 收藏文章'}</button></div><p class="eyebrow">${post.category} / ${post.date} / PROJECT NOTES</p><h1>${post.title}</h1><p class="article-summary">${post.summary}</p><div class="article-layout"><aside><p>本篇导航</p><nav aria-label="文章目录">${[...post.body.matchAll(/<h2>(.*?)<\/h2>/g)].map((m,i)=>`<a href="#heading-${i}" data-scroll="heading-${i}">${String(i+1).padStart(2,'0')} / ${m[1]}</a>`).join('')}</nav></aside><div class="article-body">${(()=>{let i=0;return post.body.replace(/<h2>/g,()=>`<h2 id="heading-${i++}" tabindex="-1">`)})()}<div class="content-credit">本文为本项目的 AI 辅助技术说明，描述站点当前实现，不作为个人经历证明。</div><a class="button primary" href="#/journal">返回日志归档 ↗</a></div></div></article>`;}
 function projects(){return `<section class="section route-section">${heading('02 / EXPERIMENTAL BUILDS','把想法<span>编译成现实</span>','一个有首领战、武器成长与三选一强化的射击跑酷，和一台可照着字母谱练习的键盘钢琴。选择作品后开始体验。')}<div class="project-grid">${Night.projects.map((p,i)=>`<button class="project" data-project="${p.id}"><div class="project-visual ${p.className}">${i===0?'<div class="orbit"><span>N/</span></div>':'<div class="wave"></div>'}<span class="visual-code">PROJECT_00${i+1}</span><span class="project-tag">${p.status}</span></div><div class="project-info"><span>${p.type} / ${p.tech}</span><h2>${p.name}<b>↗</b></h2><p>${p.description}</p></div></button>`).join('')}</div><div class="build-notes"><div><span>01 / VISUAL</span><h2>统一的视觉语言</h2><p>黄黑主色、青色辅助线、切角组件；从导航到弹窗保持一致。</p></div><div><span>02 / INTERACTION</span><h2>每一步都有回应</h2><p>按钮动态反馈、明确的成功与错误状态、可持续保存的偏好。</p></div><div><span>03 / ACCESS</span><h2>鼠标之外的选择</h2><p>支持键盘操作、Esc 关闭、可见焦点和系统减少动画偏好。</p></div></div></section>`;}
 function about(){return `<section class="section route-section">${heading('03 / IDENTITY FILE','读取<span>个人档案</span>','NEON / NEON 零界，用代码与文字记录探索。')}<div class="identity-layout"><div class="identity-card portrait-card"><div class="portrait-frame public-avatar" aria-label="NEON 抽象标识"><span aria-hidden="true">NΞON<br>零界</span></div><div class="id-top">PERSONAL ARCHIVE / 01 <span>● ONLINE</span></div><div class="portrait-name"><span>NΞON // 零界</span><strong>NEON</strong><small>ZERO DIVISION / ABSTRACT ID</small></div><div class="portrait-cross" aria-hidden="true">+</div></div><div class="identity-copy"><p class="eyebrow">BEHIND THE SCREEN</p><h2>游戏、书页，<br>还有手里的<span>魔方。</span></h2><p>我是NEON，网名 NEON / 零界。平时喜欢打游戏、读书和玩魔方。这里收集网页创作、交互作品与学习记录。</p><p>当前选择用 HTML、CSS 和 JavaScript 完成开发：让页面结构、视觉样式和交互逻辑都能直接阅读与讲解。在这里，分享这个项目的设计取舍、交互实现与迭代记录。</p><div class="skills"><span>游戏</span><span>读书</span><span>魔方</span><span>风景随拍</span></div></div></div><div class="personal-interests" aria-label="我的兴趣"><article class="interest-cell"><span>01 / GAMES</span><i class="interest-symbol" aria-hidden="true">✛</i><h2>游戏里的世界</h2><p>我的兴趣 / 打游戏</p></article><article class="interest-cell"><span>02 / BOOKS</span><i class="interest-symbol" aria-hidden="true">[ ]</i><h2>书页之间</h2><p>我的兴趣 / 读书</p></article><article class="interest-cell"><span>03 / CUBE</span><i class="interest-symbol" aria-hidden="true">▧</i><h2>指尖的魔方</h2><p>我的兴趣 / 玩魔方</p></article></div><div class="section-heading about-subheading"><div><p class="eyebrow">PROJECT EVOLUTION</p><h2>从一个想法，<span>逐步构建</span></h2></div></div><ol class="timeline"><li><span>01 / DIRECTION</span><h3>明确视觉方向</h3><p>从博客方案调研出发，选择接近 Cyberpunk 2077 的黄黑霓虹风格。</p></li><li><span>02 / PROTOTYPE</span><h3>实现第一版</h3><p>建立 SVG 城市、文章列表、阅读窗口与信号发生器。</p></li><li><span>03 / REFINEMENT</span><h3>对照课程要求完善</h3><p>改为独立路由，加入收藏、留言、本地存储和统一页面转场。</p></li></ol>${Night.gallery.preview(true)}<div class="source-panel"><h2>灵感、素材与 AI 使用</h2><p>公开源码不包含个人肖像、风景照片、图片背景和开发截图。背景由 CSS 与 Canvas 绘制。</p><p>各页交互分别采用坐标选择、档案预览、实验工作台、翻转身份卡与本地信号回执。参考了 <a href="https://github.com/cyberpunk-ui/cyberpunk-js" target="_blank" rel="noopener noreferrer">cyberpunk-js ↗</a> 的标签页思路和 <a href="https://github.com/micku7zu/vanilla-tilt.js" target="_blank" rel="noopener noreferrer">vanilla-tilt.js ↗</a> 的倾斜反馈；没有导入依赖或复制代码。不同栏目有不同的程序化过场。</p><p>新版黑红构图与荧光黄绿强调色参考荒坂企业界面和《边缘行者》的视觉方向。调研了 <a href="https://github.com/rydei/ArasakaNet" target="_blank" rel="noopener noreferrer">ArasakaNet ↗</a>、<a href="https://github.com/melendezdev/cyberpunk-edgerunners-project" target="_blank" rel="noopener noreferrer">Edgerunners 页面项目 ↗</a> 与 <a href="https://github.com/KazumiGoodProject/ascii-rain-city" target="_blank" rel="noopener noreferrer">ASCII Rain City ↗</a>；未复制代码、官方标志、角色或影视截图。</p><p>点击接入、身份确认与揭幕的交互思路参考 <a href="https://github.com/linke-e/dsh-opening-animation" target="_blank" rel="noopener noreferrer">DSH Opening Animation ↗</a> 与 <a href="https://github.com/LIYue-hope/dsh-opening-splash" target="_blank" rel="noopener noreferrer">DSH Opening Splash ↗</a>。本站使用原创 Canvas、CSS 和 N/ 标识实现，没有复制这些项目的源码或媒体。</p><p>设计参考 <a href="https://github.com/ceeyu/hexo-theme-cyberpunk2077" target="_blank" rel="noopener noreferrer">Hexo Theme Cyberpunk2077 ↗</a> 的霓虹配色、扫描线与故障风格；未复制该项目源码。背景、雨线和鼠标粒子由 CSS 与 Canvas 绘制，三刃标识由 SVG 实现，其他图形和按钮由 CSS 实现。</p><p>零界键盘钢琴参考了 <a href="https://github.com/WilliamRivasR/Virtual-Piano" target="_blank" rel="noopener noreferrer">Virtual-Piano ↗</a> 的 Web Audio 发声与琴键反馈思路，未复制其代码或音频。琴音由本站合成，三首入门谱为公版旋律的简化编配；字母为电脑按键，数字为简谱音级。</p><p>页面过场恢复为键盘钢琴上线前的程序化演出：首页穿梭夜城，日志扫描档案，作品组装线框蓝图，个人档案使用身份扫描，留言显示信号波纹。相册保留同风格的胶片与光圈动画。由 Canvas 和 CSS 绘制，原Logo保留，可用 Esc 跳过或在动效设置中关闭。</p><p>代码、网名视觉和技术说明由 Codex 辅助生成与修改。当前字体使用系统字体，不请求外部字体服务。作者需要审查、理解并按本人情况修改后再提交。</p><a class="button primary" href="#/contact">留下一段信号 ↗</a></div></section>`;}
 function contact(){return `<section class="section route-section">${heading('04 / OFFLINE MESSAGE CHANNEL','留下一段<span>信号</span>','给这个项目写建议，也可以记录下一步想实现的功能。')}<div class="contact-layout"><div><form id="message-form" novalidate><div class="form-heading"><span>NEW TRANSMISSION</span><span>LOCAL ONLY / 本地留言</span></div><label for="visitor-name">你的昵称 <small>2—20 个字符</small></label><input id="visitor-name" name="name" minlength="2" maxlength="20" required autocomplete="nickname" aria-describedby="name-error"><p class="field-error" id="name-error"></p><label for="message-topic">信号主题</label><select id="message-topic" name="topic" required aria-describedby="topic-error"><option value="">请选择主题</option><option>设计反馈</option><option>功能建议</option><option>学习交流</option></select><p class="field-error" id="topic-error"></p><label for="message-text">留言内容 <small>10—500 个字符</small></label><textarea id="message-text" name="text" rows="6" minlength="10" maxlength="500" required aria-describedby="text-error message-privacy"></textarea><div class="textarea-meta"><p class="field-error" id="text-error"></p><output id="character-count" for="message-text">0 / 500</output></div><p class="privacy-note" id="message-privacy">仅保存到当前浏览器，不会发送给作者或其他访客。请勿填写密码、学号或私人联系方式。</p><div class="form-actions"><button class="button primary" type="submit">保存到本地终端 ↗</button><button class="small-button" type="button" id="clear-draft">清除草稿</button></div><p id="form-status" role="status"></p></form></div><aside class="message-side"><p class="eyebrow">PERSISTENT LOCAL ARCHIVE</p><h2>一条留言，<br>一次<span>新的连接。</span></h2><p>输入时自动保存草稿。提交前检查格式，保存成功后显示记录；存储失败会保留输入并说明原因。</p><div class="channel-spec"><span>CHANNEL</span><strong>BROWSER STORAGE</strong><span>CAPACITY</span><strong>50 MESSAGES</strong><span>NETWORK</span><strong>NO UPLOAD</strong></div></aside></div><div class="message-archive"><div class="section-heading"><h2>当前浏览器的<span>留言记录</span></h2><div><button class="small-button" id="export-messages">导出 JSON ↓</button><button class="small-button danger" id="clear-messages">清空记录</button></div></div><div id="messages" aria-live="polite"></div></div></section>`;}
 function missing(){return `<section class="section route-section not-found">${heading('ERROR / 404','信号<span>暂时失联</span>','这个地址没有对应的页面。请使用导航或返回首页。')}<a class="button primary" href="#/home">重新接入首页 ↗</a></section>`;}
 return {home,journal,article,projects,about,contact,gallery:Night.gallery.page,missing,card};
})();

